import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    pos = int(input_data[1])
    l = int(input_data[2])
    r = int(input_data[3])

    if l == 1 and r == n:
        print(0)
        return

    ans = float('inf')

    # Option 1: Close left first, then right
    if l > 1:
        cost_left = abs(pos - l) + 1
        if r < n:
            cost_right = abs(l - r) + 1
            ans = min(ans, cost_left + cost_right)
        else:
            ans = min(ans, cost_left)
    else:
        # No need to close left
        if r < n:
            ans = min(ans, abs(pos - r) + 1)

    # Option 2: Close right first, then left
    if r < n:
        cost_right = abs(pos - r) + 1
        if l > 1:
            cost_left = abs(r - l) + 1
            ans = min(ans, cost_right + cost_left)
        else:
            ans = min(ans, cost_right)
    else:
        # No need to close right
        if l > 1:
            ans = min(ans, abs(pos - l) + 1)

    print(ans)

if __name__ == "__main__":
    solve()
